fn sin256(deg: i32) -> i32 {
    let quarter = [0, 27, 53, 79, 104, 128, 150, 171, 190, 207, 222, 234, 243, 250, 255, 256];
    let mut d: i32 = deg % 360;
    if d < 0 { d = d + 360; }
    let mut sign: i32 = 1;
    if d >= 180 {
        sign = -1;
        d = d - 180;
    }
    if d >= 90 { d = 180 - d; }
    sign * quarter[d / 6]
}

fn cos256(deg: i32) -> i32 {
    sin256(deg + 90)
}

fn dims() -> i32 {
    (256 << 16) | 128
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 4, "LIB TRIG", 0xffffff, 2);
    host::display::draw_string(120, 8, "SIN256 COS256", 0x00ff66, 1);
    host::display::fill_rect(0, 64, 256, 1, 0x303030);
    let mut x: i32 = 0;
    while x < 256 {
        let deg: i32 = x * 360 / 256;
        host::display::set_pixel(x, 64 - sin256(deg) * 44 / 256, 0x00ffcc);
        x = x + 1;
    }
    host::display::draw_number(8, 110, cos256(0), 0xffff00, 1);
    host::display::present();
}
